function getCiscoSecurexTranslation(key, lang) {
    return (ciscosecurexTranslations[lang] && ciscosecurexTranslations[lang][key]) ||
           (ciscosecurexTranslations.en && ciscosecurexTranslations.en[key]) || null;
}

function applyCiscoSecurexTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.cisco-securex.") || key.startsWith("review.common."))) {
            const translation = getCiscoSecurexTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyCiscoSecurexTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyCiscoSecurexTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyCiscoSecurexTranslations(window.i18n?.getCurrentLanguage() || "en");
}
